<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Token Radar &mdash; pre-token implied value board</title><link rel="stylesheet" href="app.css"></head><body>
<header><h1>Token Radar</h1><p class="sub">Implied pre-token value from the sealed snapshot &mdash; category comparables &bull; no hardcoded names</p></header>
<nav><input id="q" placeholder="cari nama atau slug&hellip;"><select id="cat"><option>semua kategori</option></select><select id="chain"><option>semua rantai</option></select><button id="reset">reset</button></nav>
<main id="board"><section><h2>Board <span id="count"></span></h2><table><thead><tr><th data-sort="rank">#</th><th data-sort="slug">protocol</th><th data-sort="tvl">TVL</th><th data-sort="change">7d %</th><th data-sort="implied">implied value</th><th data-sort="age">umur (hari)</th><th>kategori</th><th>rantai</th><th>rencana farming</th></tr></thead><tbody id="rows"></tbody></table></section><section id="detail" class="hidden"><h2>Detail <span id="d-name"></span></h2><div id="d-meta"></div><div id="d-model"></div><div id="d-steps"><h3>Rencana farming</h3><ol id="d-list"></ol></div><button id="d-back">kembali ke board</button></section></main>
<script src="../data.js"></script><script src="app.js"></script></body></html>
